def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    def tokenize(s: str) -> list[str]:
        toks: list[str] = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c.isspace():
                i += 1
                continue
            if c.isdigit():
                j = i + 1
                while j < n and s[j].isdigit():
                    j += 1
                toks.append(s[i:j])
                i = j
                continue
            if c.isalpha():
                if s.startswith("SUM", i) and (i + 3 == n or not s[i + 3].isalpha()):
                    toks.append("SUM")
                    i += 3
                    continue
                if s.startswith("MIN", i) and (i + 3 == n or not s[i + 3].isalpha()):
                    toks.append("MIN")
                    i += 3
                    continue
                if s.startswith("MAX", i) and (i + 3 == n or not s[i + 3].isalpha()):
                    toks.append("MAX")
                    i += 3
                    continue
                if s.startswith("IF", i) and (i + 2 == n or not s[i + 2].isalpha()):
                    toks.append("IF")
                    i += 2
                    continue
                j = i + 1
                while j < n and s[j].isdigit():
                    j += 1
                toks.append(s[i:j])
                i = j
                continue
            if s.startswith("<>", i) or s.startswith("<=", i) or s.startswith(">=", i):
                toks.append(s[i : i + 2])
                i += 2
                continue
            toks.append(c)
            i += 1
        return toks

    def is_cell(tok: str) -> bool:
        return len(tok) >= 2 and "A" <= tok[0] <= "Z" and tok[1:].isdigit()

    def parse(s: str):
        toks = tokenize(s)
        p = 0

        def peek():
            return toks[p] if p < len(toks) else None

        def pop():
            nonlocal p
            t = toks[p]
            p += 1
            return t

        def parse_expr():
            node = parse_term()
            while peek() in ("+", "-"):
                op = pop()
                right = parse_term()
                node = ("bin", op, node, right)
            return node

        def parse_term():
            node = parse_unary()
            while peek() in ("*", "/"):
                op = pop()
                right = parse_unary()
                node = ("bin", op, node, right)
            return node

        def parse_unary():
            if peek() == "-":
                pop()
                return ("neg", parse_unary())
            return parse_primary()

        def parse_primary():
            t = peek()
            if t == "(":
                pop()
                node = parse_expr()
                pop()
                return node
            if t in ("SUM", "MIN", "MAX"):
                name = pop()
                return (name, parse_args())
            if t == "IF":
                pop()
                pop()
                left = parse_expr()
                op = pop()
                right = parse_expr()
                pop()
                then_b = parse_expr()
                pop()
                else_b = parse_expr()
                pop()
                return ("IF", left, op, right, then_b, else_b)
            if t is not None and t.isdigit():
                return ("num", int(pop()))
            return ("ref", pop())

        def parse_args():
            pop()
            args = [parse_arg()]
            while peek() == ",":
                pop()
                args.append(parse_arg())
            pop()
            return args

        def parse_arg():
            t = peek()
            if t is not None and is_cell(t) and p + 1 < len(toks) and toks[p + 1] == ":":
                a = pop()
                pop()
                b = pop()
                return ("range", a, b)
            return parse_expr()

        return parse_expr()

    def col_row(name: str) -> tuple[int, int]:
        return ord(name[0]) - ord("A"), int(name[1:])

    def range_names(a: str, b: str):
        c1, r1 = col_row(a)
        c2, r2 = col_row(b)
        for r in range(min(r1, r2), max(r1, r2) + 1):
            for c in range(min(c1, c2), max(c1, c2) + 1):
                yield chr(ord("A") + c) + str(r)

    def idiv(a: int, b: int):
        if b == 0:
            return "#DIV/0!"
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    memo: dict[str, int | str] = {}
    visiting: set[str] = set()
    asts: dict[str, object] = {}

    def eval_cell(name: str):
        if name in memo:
            return memo[name]
        if name not in cells:
            return 0
        if name in visiting:
            return "#CYCLE!"
        visiting.add(name)
        raw = cells[name].strip()
        if raw.startswith("="):
            if name not in asts:
                asts[name] = parse(raw[1:])
            val = ev(asts[name])
        else:
            val = int(raw)
        visiting.remove(name)
        memo[name] = val
        return val

    def ev(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "ref":
            return eval_cell(node[1])
        if kind == "neg":
            v = ev(node[1])
            if isinstance(v, str):
                return v
            return -v
        if kind == "bin":
            op, left, right = node[1], node[2], node[3]
            lv = ev(left)
            if isinstance(lv, str):
                return lv
            rv = ev(right)
            if isinstance(rv, str):
                return rv
            if op == "+":
                return lv + rv
            if op == "-":
                return lv - rv
            if op == "*":
                return lv * rv
            return idiv(lv, rv)
        if kind == "IF":
            _, left, op, right, then_b, else_b = node
            lv = ev(left)
            if isinstance(lv, str):
                return lv
            rv = ev(right)
            if isinstance(rv, str):
                return rv
            if op == "=":
                cond = lv == rv
            elif op == "<>":
                cond = lv != rv
            elif op == "<":
                cond = lv < rv
            elif op == "<=":
                cond = lv <= rv
            elif op == ">":
                cond = lv > rv
            else:
                cond = lv >= rv
            return ev(then_b if cond else else_b)
        values: list[int] = []
        for arg in node[1]:
            if arg[0] == "range":
                for nm in range_names(arg[1], arg[2]):
                    if nm not in cells:
                        continue
                    v = eval_cell(nm)
                    if isinstance(v, str):
                        return v
                    values.append(v)
            else:
                v = ev(arg)
                if isinstance(v, str):
                    return v
                values.append(v)
        if kind == "SUM":
            return sum(values)
        if not values:
            return 0
        if kind == "MIN":
            return min(values)
        return max(values)

    return {name: eval_cell(name) for name in cells}
